package model;
import java.time.LocalDate;
public class Patient { private int patientId; private String patientCode,name,gender,bloodGroup,phone,email,address,emergencyContact; private LocalDate dateOfBirth,registrationDate; public int getPatientId(){return patientId;} public void setPatientId(int v){patientId=v;} public String getPatientCode(){return patientCode;} public void setPatientCode(String v){patientCode=v;} public String getName(){return name;} public void setName(String v){name=v;} public LocalDate getDateOfBirth(){return dateOfBirth;} public void setDateOfBirth(LocalDate v){dateOfBirth=v;} public String getGender(){return gender;} public void setGender(String v){gender=v;} public String getBloodGroup(){return bloodGroup;} public void setBloodGroup(String v){bloodGroup=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getEmergencyContact(){return emergencyContact;} public void setEmergencyContact(String v){emergencyContact=v;} public LocalDate getRegistrationDate(){return registrationDate;} public void setRegistrationDate(LocalDate v){registrationDate=v;} public String toString(){return patientCode+" - "+name;} }
